import{_ as t,o as e,c as o,a2 as s}from"./chunks/framework.BqDA2HS7.js";const m=JSON.parse('{"title":"Composite · 组合","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/composite.md","filePath":"strategies/composite.md"}'),i={name:"strategies/composite.md"};function r(d,a,l,h,n,p){return e(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="composite-·-组合" tabindex="-1">Composite · 组合 <a class="header-anchor" href="#composite-·-组合" aria-label="Permalink to &quot;Composite · 组合&quot;">​</a></h1><p>Composite 将 Task 的任务级初选，与 Stage 的后续轨迹判断组合。 它使用自己的模型池与 Judge 设置，不创建 DAG。</p><h2 id="task-与-stage-的交接" tabindex="-1">Task 与 Stage 的交接 <a class="header-anchor" href="#task-与-stage-的交接" aria-label="Permalink to &quot;Task 与 Stage 的交接&quot;">​</a></h2><ol><li>Task 在任务开始从池中选定常用模型；单候选跳过 Judge。</li><li>第一次执行直接使用常用模型，不紧接着追加 Stage Judge。</li><li>后续消费新增工具证据，必要时临时切换到指定接管模型。</li><li>保持期结束且没有新困难时恢复 Task 选出的常用模型。</li></ol><p>指定接管模型也作为 Task 正常不确定时的备援。如果初选已是接管模型，继续使用它， 跳过没有实际切换意义的判断；轨迹明确说明两者相同。</p><h2 id="两种逐轮模式" tabindex="-1">两种逐轮模式 <a class="header-anchor" href="#两种逐轮模式" aria-label="Permalink to &quot;两种逐轮模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>规则</td><td>默认窗口 3、阈值 0.5、保持 2；新增可信重复失败触发接管</td></tr><tr><td>规则＋Jev／Laya</td><td>实验协作；配置判别间隔、批次上限及降回确认</td></tr></tbody></table><p>协作模式默认隔两次执行判别，每任务最多四批，降回需要两次明确支持。 判别额度耗尽时记录冻结或保守接管原因，不继续无限追加 Judge。 本地未就绪、推论超时或进程故障按各自停止规则处理。</p><h2 id="必要设置" tabindex="-1">必要设置 <a class="header-anchor" href="#必要设置" aria-label="Permalink to &quot;必要设置&quot;">​</a></h2><p>独立模型池、Task Judge、指定接管模型、Stage 模式与参数。 接管模型必须满足能力、数据域、历史和预算要求；其角色名不证明更强。</p><h2 id="费用与轨迹" tabindex="-1">费用与轨迹 <a class="header-anchor" href="#费用与轨迹" aria-label="Permalink to &quot;费用与轨迹&quot;">​</a></h2><p>Task 一次判别与逐轮执行分别计账；纯规则 Stage 不增加 Judge。 只预留本轮选中执行模型的费用，接管余额不足明确停止，不静默降档。 轨迹包含初选、证据、保持、恢复和任何实验 Judge 的原始结果。</p>',12)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
